@Test
public void testVariantsBothRevalidated() {
    impl = new AsynchronousValidator(mockSchedulingStrategy);
    final HttpRequest req1 = new HttpGet("/");
    req1.addHeader(new BasicHeader("Accept-Encoding", "identity"));
