    } finally {
        verify(mockCacheEntry).hasVariants();
        verify(mockClient).revalidateCacheEntry(route, request, context, mockExecAware, mockCacheEntry);
        Assert.assertEquals(0, impl.getScheduledIdentifiers().size());
    }
}

